<title>Callisto</title>
<style>
  :root {
    --bg: #F6F7F9;
    --surface: #FFFFFF;
    --surface-2: #EEF1F4;
    --ink: #161B22;
    --ink-muted: #5B6572;
    --ink-faint: #8992A0;
    --line: #DFE3E8;
    --accent: #146A96;
    --accent-soft: #DCEEF6;
    --amber: #9A6413;
    --amber-soft: #F7EBD6;
    --good: #1E7A50;
    --good-soft: #DFF1E7;
    --mono: ui-monospace, "SF Mono", "Cascadia Code", "JetBrains Mono", Consolas, monospace;
    --serif: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Georgia, serif;
  }

  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --bg: #0E1217;
      --surface: #151A21;
      --surface-2: #1B222B;
      --ink: #E7EAEE;
      --ink-muted: #98A2AF;
      --ink-faint: #626D7A;
      --line: #262E38;
      --accent: #6BC0EC;
      --accent-soft: #16303C;
      --amber: #E3B15E;
      --amber-soft: #362A16;
      --good: #7ED4A8;
      --good-soft: #163427;
    }
  }

  :root[data-theme="dark"] {
    --bg: #0E1217;
    --surface: #151A21;
    --surface-2: #1B222B;
    --ink: #E7EAEE;
    --ink-muted: #98A2AF;
    --ink-faint: #626D7A;
    --line: #262E38;
    --accent: #6BC0EC;
    --accent-soft: #16303C;
    --amber: #E3B15E;
    --amber-soft: #362A16;
    --good: #7ED4A8;
    --good-soft: #163427;
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    background: var(--bg);
    color: var(--ink);
    font-family: var(--serif);
    font-size: 17px;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
  }

  ::selection { background: var(--accent-soft); }

  .page {
    max-width: 780px;
    margin: 0 auto;
    padding: 64px 28px 96px;
  }

  .eyebrow {
    font-family: var(--mono);
    font-size: 12px;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    color: var(--ink-faint);
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .eyebrow .dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--good);
    box-shadow: 0 0 0 3px var(--good-soft);
    flex: none;
  }

  header.hero {
    margin-bottom: 52px;
  }

  h1 {
    font-family: var(--mono);
    font-weight: 600;
    font-size: clamp(34px, 6vw, 46px);
    letter-spacing: -0.01em;
    margin: 14px 0 10px;
    text-wrap: balance;
  }

  .tagline {
    font-size: 19px;
    color: var(--ink-muted);
    max-width: 60ch;
    margin: 0;
  }

  .stat-row {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1px;
    background: var(--line);
    border: 1px solid var(--line);
    border-radius: 10px;
    overflow: hidden;
    margin-top: 36px;
  }

  .stat {
    background: var(--surface);
    padding: 18px 16px;
  }

  .stat .num {
    font-family: var(--mono);
    font-variant-numeric: tabular-nums;
    font-size: 26px;
    font-weight: 600;
    color: var(--ink);
    line-height: 1.1;
  }

  .stat .label {
    font-family: var(--mono);
    font-size: 11px;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--ink-faint);
    margin-top: 6px;
  }

  section {
    margin-top: 56px;
  }

  section > .eyebrow {
    margin-bottom: 16px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--line);
  }

  h2 {
    font-family: var(--mono);
    font-size: 15px;
    font-weight: 600;
    letter-spacing: 0.02em;
    color: var(--ink);
    margin: 0;
  }

  p { margin: 0 0 14px; }
  p:last-child { margin-bottom: 0; }

  .lede {
    font-size: 17.5px;
    color: var(--ink);
    max-width: 66ch;
  }

  .cap-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
    margin-top: 24px;
  }

  .cap {
    background: var(--surface);
    border: 1px solid var(--line);
    border-radius: 8px;
    padding: 16px 18px;
  }

  .cap .cap-title {
    font-family: var(--mono);
    font-size: 12.5px;
    font-weight: 600;
    color: var(--accent);
    margin-bottom: 6px;
  }

  .cap .cap-body {
    font-size: 14.5px;
    color: var(--ink-muted);
    line-height: 1.55;
  }

  .timeline {
    border-left: 2px solid var(--line);
    margin-left: 4px;
