          <div class="tier-status queued">queued</div>
        </div>
        <div class="tier">
          <div class="tier-num">03</div>
          <div class="tier-name">Dependency hygiene<span class="sub">Fix a real Unix path bug, centralize re-pinned versions, drop dead weight</span></div>
          <div class="tier-status queued">queued</div>
        </div>
        <div class="tier">
          <div class="tier-num">04</div>
