86	/// Unified git-data access surface covering every operation callisto's
87	/// release-graph logic needs, independent of *how* the data is sourced.
88	///
89	/// Two backends implement this trait:
90	///
91	/// - [`GitRepository`] -- native, backed by `gix`. Fast and side-effect-free
92	///   for reads, but entirely unavailable on `wasm32` (gix is excluded from
93	///   that target's dependency set, so [`GitRepository::discover`] always
94	///   returns `Err` there).
95	/// - [`ShellGit`] -- shells out to the real `git` binary via a
96	///   [`callisto_model::CommandRunner`], so it works everywhere a `git`
97	///   binary is reachable, including through the `wasm32`/Extism host
98	///   bridge.
99	///
100	/// Callers should not implement or select between these directly; use
101	/// [`GitAccess::discover`], which tries native `gix` first and transparently
102	/// falls back to the `CommandRunner` shell-out, applying the correct
103	/// per-operation fallback policy (see [`GitAccess`]'s docs).
104	pub trait GitDataSource {
105	    /// Returns the commit SHA that `HEAD` currently resolves to.
106	    fn head_sha(&self) -> Result<CommitSha, VcsError>;
107	
108	    /// Lists tag names, optionally filtered by `glob` (a [`globset::Glob`]
109	    /// pattern). Both backends filter with the exact same `globset`
110	    /// matching semantics, so tag selection is byte-identical regardless of
111	    /// which one served the request. `None` matches every tag.
112	    fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError>;
113	
114	    /// Resolves `refname` (tag, branch, or partial/full SHA) to the commit
115	    /// it points at. An unresolvable ref is *not* an error -- it resolves
116	    /// to `Ok(None)`, which callers typically treat as "no bound" / "infer
117	    /// over full history".
118	    fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError>;
119	
120	    /// Lists commits reachable from `HEAD`, down to (exclusive) `since_ref`
121	    /// when given, filtered to those that touch at least one of
122	    /// `pathspecs` (an empty slice disables filtering and returns every
123	    /// commit in the walk). Merge commits are always excluded, matching
124	    /// `git log --no-merges`.
125	    ///
126	    /// Unlike [`Self::resolve_commit`], a `since_ref` that's given but
127	    /// fails to resolve to a commit *is* an error: silently ignoring it and
128	    /// walking unbounded history instead of the caller's requested bound
129	    /// is a correctness bug (e.g. it can re-surface already-released
130	    /// commits into changelog/severity inference). `since_ref: None` is not
131	    /// this case -- it's a deliberate request for the full history and
132	    /// always succeeds.
133	    fn commits_since(
134	        &self,
135	        since_ref: Option<&str>,
136	        pathspecs: &[PathBuf],
137	    ) -> Result<Vec<GitCommit>, VcsError>;
138	
139	    /// Creates the tag `name` at `target_sha`: annotated with `message`
140	    /// when `Some`, lightweight when `None`. Fails if a ref of that name
141	    /// already exists.
142	    ///
143	    /// Writes a git ref, so it requires an [`ApplyPermit`]; a dry run has
144	    /// none to give and therefore cannot call this at all.
145	    fn create_tag(
146	        &self,
147	        name: &str,
148	        target_sha: &CommitSha,
149	        message: Option<&str>,
150	        permit: &ApplyPermit,
151	    ) -> Result<(), VcsError>;
152	
153	    /// Force-creates or -moves the floating tag `major_name` to point at
154	    /// `target_sha`, overwriting any existing ref of that name.
155	    ///
156	    /// Writes a git ref, so it requires an [`ApplyPermit`].
157	    fn create_floating_major(
158	        &self,
159	        major_name: &str,
160	        target_sha: &CommitSha,
161	        permit: &ApplyPermit,
162	    ) -> Result<(), VcsError>;
163	}
