222	                .map_err(|e| VcsError::Git(format!("Failed to get HEAD commit: {e}")))?;
223	            CommitSha::parse(&head.id.to_hex().to_string())
224	                .map_err(|e| VcsError::Git(format!("Invalid HEAD SHA: {e}")))
225	        }
