316	    /// Like [`Self::commits_since`], but additionally filters the walked
317	    /// commits down to those that touched at least one path under one of
318	    /// the given `pathspecs`.
319	    ///
320	    /// `pathspecs` are matched as simple path prefixes against every path
321	    /// touched by a commit's tree diff against its (first) parent -- a
322	    /// pathspec matches a changed path if the changed path is exactly equal
323	    /// to it, or the changed path is nested underneath it as a directory
324	    /// prefix. This mirrors the directory/path-prefix scoping `git log --
325	    /// <pathspecs>` provides for per-package commit filtering; it does not
326	    /// implement full git pathspec magic syntax (`:!`, glob magic, etc).
327	    ///
328	    /// An empty `pathspecs` slice disables filtering entirely and returns
329	    /// every commit in the walk, matching `git log` with no trailing `--`
330	    /// pathspec.
331	    ///
332	    /// `since` is an exclusive lower bound, same as `commits_since`'s
333	    /// `from_ref`: the commit `since` points at is not itself included in
334	    /// the result.
335	    ///
336	    /// Merge commits (more than one parent) are skipped, matching `git log
337	    /// --no-merges` -- this method exists to power per-package commit
338	    /// scoping for severity inference, where a merge commit's message
339	    /// duplicates work already represented by its non-merge ancestors.
340	    pub fn commits_since_with_pathspec(
341	        &self,
342	        since: Option<&CommitSha>,
343	        pathspecs: &[PathBuf],
344	    ) -> Result<Vec<GitCommit>, VcsError> {
345	        #[cfg(not(target_arch = "wasm32"))]
346	        {
347	            let head = self
348	                .repo
349	                .head_commit()
350	                .map_err(|e| VcsError::Git(format!("Failed to get HEAD commit: {e}")))?;
351	
352	            let revwalk = self
353	                .repo
354	                .rev_walk(vec![head.id])
355	                .all()
356	                .map_err(|e| VcsError::Git(format!("Failed to create revwalk: {e}")))?;
357	
358	            // Build the excluded set: all SHAs reachable from `since`
359	            // (inclusive). Using `continue` rather than `break` is critical
360	            // for branchy history: a topological walk can visit the `since`
361	            // commit before it has emitted all commits on merged branches
362	            // that diverged *before* the tag. A `break` would silently drop
363	            // those in-queue commits; `continue` skips only the already-seen
364	            // ancestors.
365	            let excluded: std::collections::HashSet<String> = if let Some(s) = since {
366	                let since_oid = gix::ObjectId::from_hex(s.as_ref().as_bytes())
367	                    .map_err(|e| VcsError::Git(format!("Invalid since SHA: {e}")))?;
368	                let since_walk = self
369	                    .repo
370	                    .rev_walk(vec![since_oid])
371	                    .all()
372	                    .map_err(|e| VcsError::Git(format!("Failed to walk from since: {e}")))?;
373	                let mut set = std::collections::HashSet::new();
374	                for info in since_walk {
375	                    let info = info.map_err(|e| VcsError::Git(e.to_string()))?;
376	                    set.insert(info.id.to_hex().to_string());
377	                }
378	                set
379	            } else {
380	                std::collections::HashSet::new()
381	            };
382	
383	            let mut commits = Vec::new();
384	            for info in revwalk {
385	                let info = info.map_err(|e| VcsError::Git(e.to_string()))?;
386	                let hex = info.id.to_hex().to_string();
387	
388	                if excluded.contains(&hex) {
389	                    continue;
390	                }
391	
392	                if info.parent_ids().count() > 1 {
393	                    continue;
394	                }
395	
396	                let commit_obj = info
397	                    .object()
398	                    .map_err(|e| VcsError::Git(format!("Failed to load commit object: {e}")))?;
399	
400	                if !pathspecs.is_empty() {
401	                    let touched =
402	                        commit_touches_pathspecs(&self.repo, &info, &commit_obj, pathspecs)?;
403	                    if !touched {
404	                        continue;
405	                    }
406	                }
407	
408	                let sha = CommitSha::parse(&hex)
409	                    .map_err(|e| VcsError::Git(format!("Invalid commit SHA: {e}")))?;
410	
411	                let message = commit_obj
412	                    .message()
413	                    .map_err(|e| VcsError::Git(e.to_string()))?;
414	                let summary = message
415	                    .title
416	                    .to_string()
417	                    .replace("\r\n", "\n")
418	                    .trim_end()
419	                    .to_string();
420	                let body = message.body.map(|b| b.to_string().replace("\r\n", "\n"));
421	
422	                commits.push(GitCommit { sha, summary, body });
423	            }
424	
425	            Ok(commits)
426	        }
427	        #[cfg(target_arch = "wasm32")]
428	        {
429	            let _unused = (since, pathspecs);
430	            Ok(Vec::new())
431	        }
432	    }
