1091	    /// Spec: `GitRepository::commits_since_with_pathspec` must not panic when
1092	    /// HEAD is detached (i.e., no branch is checked out). Detached HEAD is a
1093	    /// valid and common repository state (e.g. after `git checkout <sha>`,
1094	    /// during a rebase, or in CI). The method must either return commits
1095	    /// reachable from HEAD or a clear `VcsError`, never an unwrap panic.
1096	    #[test]
1097	    fn test_commits_since_detached_head_does_not_panic() {
1098	        let ws_dir = tempfile::tempdir().unwrap();
1099	        let root = ws_dir.path();
1100	        init_repo(root);
1101	
1102	        // Commit #1 – the one we will check out by SHA to detach HEAD.
1103	        std::fs::write(root.join("a.txt"), "first\n").unwrap();
1104	        run_git(root, &["add", "."]);
1105	        run_git(root, &["commit", "-q", "-m", "feat: first commit"]);
1106	
1107	        let sha_out = std::process::Command::new("git")
1108	            .args(["rev-parse", "HEAD"])
1109	            .current_dir(root)
1110	            .output()
1111	            .unwrap();
1112	        let first_sha = String::from_utf8_lossy(&sha_out.stdout).trim().to_string();
1113	
1114	        // Commit #2 – created on the branch so detaching at #1 leaves it
1115	        // unreachable from HEAD.
1116	        std::fs::write(root.join("b.txt"), "second\n").unwrap();
1117	        run_git(root, &["add", "."]);
1118	        run_git(root, &["commit", "-q", "-m", "feat: second commit"]);
1119	
1120	        // Detach HEAD by checking out the first commit SHA directly.
1121	        run_git(root, &["checkout", "-q", &first_sha]);
1122	
1123	        let repo = GitRepository::discover(root).unwrap();
1124	
1125	        // Must not panic; Ok with at least one commit is the expected outcome.
1126	        let result = repo.commits_since_with_pathspec(None, &[]);
1127	        match result {
1128	            Ok(commits) => {
1129	                // Detached HEAD at commit #1: only that commit is reachable.
1130	                assert_eq!(
1131	                    commits.len(),
1132	                    1,
1133	                    "expected 1 commit reachable from detached HEAD; got {:?}",
1134	                    commits.len()
1135	                );
1136	                assert_eq!(commits[0].summary, "feat: first commit");
1137	            }
1138	            Err(e) => {
1139	                // A clear VcsError (not a panic) is acceptable as a fallback,
1140	                // but gix reads detached HEAD just fine, so this arm should
1141	                // not be reached in practice.
1142	                assert!(
1143	                    matches!(e, VcsError::Git(_)),
1144	                    "unexpected error type from detached HEAD: {e:?}"
1145	                );
1146	            }
1147	        }
1148	    }
