1	//! Central native-`gix`-first, `CommandRunner`-shell-fallback selection
2	//! logic for [`GitDataSource`], replacing the `if let Ok(repo) = ... { if
3	//! let Ok(x) = repo.op(...) { return x } } /* fall through */` boilerplate
4	//! that used to be hand-rolled independently at five call sites across
5	//! `callisto-graph` and `callisto-conventional`.
6	
7	use std::path::{Path, PathBuf};
8	
9	use callisto_model::{ApplyPermit, CommandRunner, CommitSha, TagName};
10	
11	use crate::{GitCommit, GitDataSource, GitRepository, ShellGit, VcsError};
12	
13	/// Selects between native `gix` ([`GitRepository`]) and a `CommandRunner`
14	/// shell-out ([`ShellGit`]) per operation, so callers never have to.
15	///
16	/// Construct via [`GitAccess::discover`], then call [`GitDataSource`]
17	/// methods directly -- there is no branching visible at the call site.
18	///
19	/// **Fallback policy differs by operation category, deliberately:**
20	///
21	/// - **Read operations** ([`GitDataSource::list_tags`],
22	///   [`GitDataSource::resolve_commit`], [`GitDataSource::commits_since`]):
23	///   fall back to the shell backend whenever native `gix` errors for *any*
24	///   reason -- failed discovery (`wasm32`, or the root simply isn't a repo)
25	///   as well as a discovered repo's operation itself failing. Retrying a
26	///   read through the shell can only help: at worst it fails too and the
27	///   error propagates from there instead.
28	/// - **Write operations** ([`GitDataSource::create_tag`],
29	///   [`GitDataSource::create_floating_major`]): fall back to the shell
30	///   *only* when native `gix` was never available to begin with (discovery
31	///   failed). If a repo *was* discovered, its result -- success or failure
32	///   -- is authoritative and returned as-is. Retrying a failed mutation
33	///   through a second, different code path risks masking a genuine
34	///   failure (or double-applying a mutation the first attempt partially
35	///   completed), which read-only retries don't risk.
36	pub struct GitAccess<'r> {
37	    native: Option<GitRepository>,
38	    shell: ShellGit<'r>,
39	}
40	
41	impl<'r> GitAccess<'r> {
42	    /// Tries to discover a native `gix` repository at `root`; regardless of
43	    /// whether that succeeds, also prepares the `CommandRunner`-shelled
44	    /// backend against the same `root`, ready to serve as a fallback (reads)
45	    /// or as the sole backend (writes, when discovery failed).
46	    ///
47	    /// Never fails: a discovery failure just means every operation runs
48	    /// through the shell backend instead, exactly as it unconditionally
49	    /// does on `wasm32` (gix is excluded from that target's dependency set,
50	    /// so [`GitRepository::discover`] always returns `Err` there).
51	    pub fn discover(root: impl AsRef<Path>, runner: &'r dyn CommandRunner) -> Self {
52	        let root = root.as_ref();
53	        GitAccess {
54	            native: GitRepository::discover(root).ok(),
55	            shell: ShellGit::new(runner, root.to_path_buf()),
56	        }
57	    }
58	}
59	
60	impl GitDataSource for GitAccess<'_> {
61	    fn head_sha(&self) -> Result<CommitSha, VcsError> {
62	        if let Some(repo) = &self.native {
63	            if let Ok(sha) = repo.head_sha() {
64	                return Ok(sha);
65	            }
66	        }
67	        self.shell.head_sha()
68	    }
69	
70	    fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError> {
71	        if let Some(repo) = &self.native {
72	            if let Ok(tags) = repo.list_tags(glob) {
73	                return Ok(tags);
74	            }
75	        }
76	        self.shell.list_tags(glob)
77	    }
78	
79	    fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
80	        if let Some(repo) = &self.native {
81	            if let Ok(sha) = repo.resolve_commit(refname) {
82	                return Ok(sha);
83	            }
84	        }
85	        self.shell.resolve_commit(refname)
86	    }
87	
88	    fn commits_since(
89	        &self,
90	        since_ref: Option<&str>,
91	        pathspecs: &[PathBuf],
92	    ) -> Result<Vec<GitCommit>, VcsError> {
93	        if let Some(repo) = &self.native {
94	            if let Ok(commits) = repo.commits_since(since_ref, pathspecs) {
95	                return Ok(commits);
96	            }
97	        }
98	        self.shell.commits_since(since_ref, pathspecs)
99	    }
100	
101	    fn create_tag(
102	        &self,
103	        name: &str,
104	        target_sha: &CommitSha,
105	        message: Option<&str>,
106	        permit: &ApplyPermit,
107	    ) -> Result<(), VcsError> {
108	        if let Some(repo) = &self.native {
109	            // Authoritative: a genuine gix failure must not be masked by
110	            // silently retrying through the shell.
111	            return repo.create_tag(name, target_sha, message, permit);
112	        }
113	        self.shell.create_tag(name, target_sha, message, permit)
114	    }
115	
116	    fn create_floating_major(
117	        &self,
118	        major_name: &str,
119	        target_sha: &CommitSha,
120	        permit: &ApplyPermit,
121	    ) -> Result<(), VcsError> {
122	        if let Some(repo) = &self.native {
123	            return repo.create_floating_major(major_name, target_sha, permit);
124	        }
125	        self.shell
126	            .create_floating_major(major_name, target_sha, permit)
127	    }
128	}
