148	/// Strips a URL's userinfo component (`user:pass@` between `scheme://`
149	/// and the host) from every `scheme://...` occurrence in `text`,
150	/// replacing it with `[REDACTED]@`. Operates token-by-token: within the
151	/// span from `scheme://` to the next whitespace/quote/`<`/`>` character,
152	/// everything up to the *last* `@` is treated as userinfo and redacted.
153	///
154	/// This is deliberately conservative rather than strictly RFC 3986-aware:
155	/// userinfo containing a raw `/` or a second `@` (e.g. an unescaped
156	/// base64-ish token) is realistic in free-form CLI stderr text, and using
157	/// the *first* `@` (or bailing out on any `/` before it) would under-
158	/// redact exactly that case -- the one this function exists to catch. The
159	/// cost is a rare false positive (an `@` that's actually part of a path,
160	/// e.g. an npm scoped package name in `registry.npmjs.org/@myorg/pkg`,
161	/// gets redacted too) — acceptable, since over-redaction only costs log
162	/// noise while under-redaction leaks a credential.
163	fn redact_url_userinfo(text: &str) -> String {
164	    let mut result = String::with_capacity(text.len());
165	    let mut rest = text;
166	    while let Some(scheme_pos) = rest.find("://") {
167	        let split_at = scheme_pos + 3;
168	        result.push_str(&rest[..split_at]);
169	        let after = &rest[split_at..];
170	        let stop = after
171	            .find(|c: char| c.is_whitespace() || matches!(c, '"' | '\'' | '<' | '>'))
172	            .unwrap_or(after.len());
173	        let candidate = &after[..stop];
174	        if let Some(at_pos) = candidate.rfind('@') {
175	            result.push_str("[REDACTED]@");
176	            rest = &after[at_pos + 1..];
177	            continue;
178	        }
179	        rest = after;
180	    }
181	    result.push_str(rest);
182	    result
183	}
