22	/// Resolves each changeset entry to at most one package and accumulates the
23	/// pending changeset names and max severity per package.
24	///
25	/// Uses [`resolve_target_package`] (the same ambiguity-checking resolution
26	/// `aggregate()` relies on) rather than a bare `matches()` loop, so a
27	/// changeset entry naming a bare package that exists in two or more
28	/// ecosystems (e.g. `cargo/foo` and `npm/foo`) errors instead of silently
29	/// attaching the changeset to every matching package.
30	fn resolve_pending_changesets<'a>(
31	    packages: impl Iterator<Item = &'a Package> + Clone,
32	    loaded_changesets: &[LoadedChangeset],
33	) -> Result<PendingChangesets, GraphError> {
34	    let mut pending: PendingChangesets = BTreeMap::new();
35	    for lc in loaded_changesets {
36	        for entry in &lc.changeset.entries {
37	            let Ok(entry_id) = PackageId::parse(&entry.name) else {
38	                continue;
39	            };
40	            let Some(resolved) = resolve_target_package(packages.clone(), &entry_id)? else {
41	                continue;
42	            };
43	            let name = lc
44	                .path
45	                .file_stem()
46	                .and_then(|s| s.to_str())
47	                .unwrap_or("unknown")
48	                .to_string();
49	            let state = pending.entry(resolved.id.clone()).or_default();
50	            state.0.push(name);
51	            state.1 = match (state.1, entry.severity) {
52	                (None, s) => Some(s),
53	                (Some(cur), s) => Some(cur.max(s)),
54	            };
55	        }
56	    }
57	    Ok(pending)
58	}
